use serde::{Deserialize,Serialize}; use crate::fea::StressGrid; use crate::geom::{self,Vec3};
#[derive(Clone,Debug,Serialize,Deserialize)] pub struct GoverningScalar{pub origin:Vec3,pub spacing:Vec3,pub dims:[usize;3],pub values:Vec<f64>,pub gradients:Vec<Vec3>}
impl GoverningScalar{pub fn is_empty(&self)->bool{self.values.is_empty()||self.dims.iter().product::<usize>()==0}pub fn index(&self,i:usize,j:usize,k:usize)->usize{i+j*self.dims[0]+k*self.dims[0]*self.dims[1]}pub fn position(&self,i:usize,j:usize,k:usize)->Vec3{[self.origin[0]+i as f64*self.spacing[0],self.origin[1]+j as f64*self.spacing[1],self.origin[2]+k as f64*self.spacing[2]]}pub fn range(&self)->(f64,f64){(self.values.iter().cloned().fold(f64::INFINITY,f64::min),self.values.iter().cloned().fold(f64::NEG_INFINITY,f64::max))}}
pub fn build_governing_scalar(g:&StressGrid)->GoverningScalar{if g.is_empty(){return GoverningScalar{origin:g.origin,spacing:g.spacing,dims:[0,0,0],values:Vec::new(),gradients:Vec::new()}}let n=g.len();let mut v=vec![0.0;n];for k in 0..g.dims[2]{for j in 0..g.dims[1]{for i in 0..g.dims[0]{let idx=g.index(i,j,k);v[idx]=(i as f64*g.spacing[0]+j as f64*g.spacing[1]+k as f64*g.spacing[2]);}}}GoverningScalar{origin:g.origin,spacing:g.spacing,dims:g.dims,values:v,gradients:g.directions.clone()}}
